(35728, 123435, 0, 2, 'Show me where I can fly.', 12271, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978), -- OptionBroadcastTextID: 12271 - 140511 - 158191
(40076, 136778, 1, 0, 'Who are you?', 25092, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978), -- OptionBroadcastTextID: 25092 - 38470 - 47091 - 47632 - 62792 - 65124 - 79414 - 97339 - 153888 - 161428 - 166571 - 176081 - 185133 - 224837 - 263541 - 298152
(40076, 136776, 3, 0, 'Where can I find decor?', 0, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(40076, 136775, 4, 0, 'Are you really giving away treasure?', 0, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(41191, 136950, 2, 0, 'I\'m interested in founding my own neighborhood.', 0, 0, 0, 41196, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(41196, 136961, 2, 0, 'I\'d like to talk about something else.', 0, 0, 0, 41191, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(41352, 137143, 1, 0, 'I\'d like to upgrade my house.', 0, 0, 0, 41354, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(41354, 137142, 0, 0, 'I\'ll be back.', 0, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(41379, 137165, 1, 0, 'Can I use this device to make dyes?', 0, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
(41379, 137172, 2, 0, 'Where else can I obtain dyes?', 0, 0, 0, 0, 0, NULL, 0, 0, NULL, 0, NULL, NULL, 64978),
