SET @NPCTEXTID := 16800001;

-- ============================================================================
-- Phase 4: Database Cleanup - Remove ALL existing housing spawns
-- ============================================================================

-- Alliance neighborhood (map 2735)
DELETE FROM creature_addon WHERE guid IN (SELECT guid FROM creature WHERE map = 2735);
DELETE FROM creature WHERE map = 2735;
DELETE FROM gameobject_addon WHERE guid IN (SELECT guid FROM gameobject WHERE map = 2735);
DELETE FROM gameobject WHERE map = 2735;

-- Horde neighborhood (map 2736)
DELETE FROM creature_addon WHERE guid IN (SELECT guid FROM creature WHERE map = 2736);
DELETE FROM creature WHERE map = 2736;
DELETE FROM gameobject_addon WHERE guid IN (SELECT guid FROM gameobject WHERE map = 2736);
DELETE FROM gameobject WHERE map = 2736;

-- Remove anomalous 18-19 digit GUIDs
DELETE FROM gameobject WHERE map = 2735 AND guid > 999999999;


