DELETE FROM `creature_queststarter` WHERE (`id`=248854 AND `quest`=92982) OR (`id`=233063 AND `quest`=91863) OR (`id`=209790 AND `quest`=77408);

DELETE FROM `creature_questender` WHERE (`id`=233063 AND `quest`=91863);


