-- ============================================================================
-- Supplemental Data: NPC Text
-- ============================================================================

DELETE FROM `npc_text` WHERE `ID` BETWEEN @NPCTEXTID+0 AND @NPCTEXTID+6;


-- ============================================================================
-- Supplemental Data: Gossip Menu
-- ============================================================================

DELETE FROM `gossip_menu` WHERE (`MenuID`=40076 AND `TextID`=@NPCTEXTID+0) OR (`MenuID`=41191 AND `TextID`=@NPCTEXTID+1) OR (`MenuID`=41379 AND `TextID`=@NPCTEXTID+2) OR (`MenuID`=41196 AND `TextID`=@NPCTEXTID+3) OR (`MenuID`=41352 AND `TextID`=@NPCTEXTID+4) OR (`MenuID`=35728 AND `TextID`=@NPCTEXTID+5) OR (`MenuID`=41354 AND `TextID`=@NPCTEXTID+6);


-- ============================================================================
-- Supplemental Data: Gossip Menu Options
-- ============================================================================

DELETE FROM `gossip_menu_option` WHERE (`OptionID`=0 AND `MenuID` IN (35728,41354)) OR (`OptionID`=1 AND `MenuID` IN (40076,41352,41379)) OR (`OptionID`=3 AND `MenuID` IN (40076,41379)) OR (`OptionID`=4 AND `MenuID`=40076) OR (`OptionID`=2 AND `MenuID` IN (41191,41196,41379));


-- ============================================================================
-- Missing AreaTrigger Create Properties (DB2 stubs)
-- ============================================================================
-- These non-custom AreaTriggerCreateProperties IDs are referenced by spells cast
-- by housing neighborhood creatures but are missing from the TDB (newer DB2 data).
-- Without these entries, the server logs ~283 errors per spawn cycle.
-- Creatures affected:
--   37231: Mechanotank (248536), Public Carriage (242053, 256630) - spell 1252485/1269421
--   37232: Same creatures - companion areatrigger from same spell chain
--   39419: Local NPCs (245134) - spell 1239425/1243786
--   39877: Mechagon Air Jet (252876) - spell 1277716 (139 spawns on map 2735)
--   41322: Local NPCs (245134) - companion areatrigger

DELETE FROM `areatrigger_create_properties` WHERE (`Id` IN (37231, 37232, 39419, 39877, 41322) AND `IsCustom` = 0);


-- ============================================================================
-- NPC Flag Restoration
-- ============================================================================
-- WPP creature_template output captures limited npcflag data from client.
-- Restore correct npcflags from relationship tables (npc_vendor, queststarter, etc.)

-- Set VENDOR flag (128) for entries with npc_vendor data
UPDATE creature_template ct
SET ct.npcflag = ct.npcflag | 128
WHERE ct.entry IN (SELECT DISTINCT entry FROM npc_vendor)
AND (ct.npcflag & 128) = 0;

-- Set QUESTGIVER flag (2) for quest starters and enders
UPDATE creature_template ct
SET ct.npcflag = ct.npcflag | 2
WHERE ct.entry IN (
  SELECT DISTINCT id FROM creature_queststarter
  UNION
  SELECT DISTINCT id FROM creature_questender
)
AND (ct.npcflag & 2) = 0;

-- Set GOSSIP flag (1) for entries with gossip menus
UPDATE creature_template ct
SET ct.npcflag = ct.npcflag | 1
WHERE ct.entry IN (SELECT DISTINCT CreatureID FROM creature_template_gossip)
AND (ct.npcflag & 1) = 0;
